import{_ as e,c as t,o as r,ai as n}from"./chunks/framework.BrjRfu4a.js";const c=JSON.parse('{"title":"외국인 채권투자 동향 | 2024년 국고채 시장 | 한국 국채","description":"외국인의 원화채권 보유잔액은 2017년 100조원 수준에서 매년 최고치를 경신하며 현재까지 꾸준히 증가세를 유지해오고 있습니다. 특히 2020년~2021년은 코로나 팬데믹 대응 과정에서 확대된 유동성과 완화적 통화정책에 힘입어 외국인 채권 투자가 역대 최대 규모로 유입된 바 있습니다.","frontmatter":{"title":"외국인 채권투자 동향 | 2024년 국고채 시장 | 한국 국채","description":"외국인의 원화채권 보유잔액은 2017년 100조원 수준에서 매년 최고치를 경신하며 현재까지 꾸준히 증가세를 유지해오고 있습니다. 특히 2020년~2021년은 코로나 팬데믹 대응 과정에서 확대된 유동성과 완화적 통화정책에 힘입어 외국인 채권 투자가 역대 최대 규모로 유입된 바 있습니다.","head":[["meta",{"property":"og:title","content":"외국인 채권투자 동향 | 2024년 국고채 시장 | 한국 국채"}],["meta",{"property":"og:description","content":"외국인의 원화채권 보유잔액은 2017년 100조원 수준에서 매년 최고치를 경신하며 현재까지 꾸준히 증가세를 유지해오고 있습니다. 특히 2020년~2021년은 코로나 팬데믹 대응 과정에서 확대된 유동성과 완화적 통화정책에 힘입어 외국인 채권 투자가 역대 최대 규모로 유입된 바 있습니다."}],["meta",{"property":"og:image","content":"/images/RiskQuantHaun.png"}],["meta",{"property":"og:url","content":"https://risk-quant-haun.github.io/ko/korean-treasury-bonds/2024-market/foreign-investment-trends"}],["link",{"rel":"alternate","hreflang":"ko","href":"https://risk-quant-haun.github.io/ko/korean-treasury-bonds/2024-market/foreign-investment-trends"}],["link",{"rel":"alternate","hreflang":"en","href":"https://risk-quant-haun.github.io/korean-treasury-bonds/2024-market/foreign-investment-trends"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://risk-quant-haun.github.io/ko/korean-treasury-bonds/2024-market/foreign-investment-trends"}],["link",{"rel":"canonical","href":"https://risk-quant-haun.github.io/ko/korean-treasury-bonds/2024-market/foreign-investment-trends"}]],"date":"2025-03-09T00:00:00.000Z"},"headers":[],"relativePath":"ko/korean-treasury-bonds/2024-market/foreign-investment-trends.md","filePath":"ko/korean-treasury-bonds/2024-market/foreign-investment-trends.md"}'),o={name:"ko/korean-treasury-bonds/2024-market/foreign-investment-trends.md"};function i(l,a,s,h,d,u){return r(),t("div",null,a[0]||(a[0]=[n('<h1 id="🏦-외국인-채권투자-동향" tabindex="-1">🏦 외국인 채권투자 동향 <a class="header-anchor" href="#🏦-외국인-채권투자-동향" aria-label="Permalink to &quot;🏦 외국인 채권투자 동향&quot;">​</a></h1><p><strong>2024년 국고채 시장 | 한국 국채 | 2025.03.09</strong></p><h2 id="_1️⃣-개요" tabindex="-1">1️⃣ 개요 <a class="header-anchor" href="#_1️⃣-개요" aria-label="Permalink to &quot;1️⃣ 개요&quot;">​</a></h2><p>외국인의 원화채권 보유잔액은 2017년 100조원 수준에서 매년 최고치를 경신하며 현재까지 꾸준히 증가세를 유지해오고 있습니다. 특히 2020년~2021년은 코로나 팬데믹 대응 과정에서 확대된 유동성과 완화적 통화정책에 힘입어 외국인 채권 투자가 역대 최대 규모로 유입된 바 있습니다. 2022년~2023년에는 글로벌 통화긴축 등 영향으로 유입폭은 축소되었으나, 양호한 유입흐름을 기록하였습니다.</p><h2 id="_2️⃣-2024년-투자-동향" tabindex="-1">2️⃣ 2024년 투자 동향 <a class="header-anchor" href="#_2️⃣-2024년-투자-동향" aria-label="Permalink to &quot;2️⃣ 2024년 투자 동향&quot;">​</a></h2><p>2024년에는 글로벌 금리인하 추세에 따른 외국인 투자심리 개선에 더하여, 세계국채지수(WGBI) 편입결정(&#39;24.10월) 및 국채통합계좌 개통(&#39;24.6월), 외환시장 구조개선(&#39;24.7월) 등 투자여건 개선에 힘입어 외국인 원화채 순유입(+25.1조원)이 크게 확대되었습니다. 이는 2021년(+63.9조원) 이후 3년만에 최대폭의 순유입으로, 외국인 원화채권 보유잔액(268.2조원)과 보유비중(10.4%)도 역대 최대치를 경신하였습니다.</p><h2 id="_3️⃣-채권-종류별-투자-현황" tabindex="-1">3️⃣ 채권 종류별 투자 현황 <a class="header-anchor" href="#_3️⃣-채권-종류별-투자-현황" aria-label="Permalink to &quot;3️⃣ 채권 종류별 투자 현황&quot;">​</a></h2><h3 id="국고채-투자" tabindex="-1">국고채 투자 <a class="header-anchor" href="#국고채-투자" aria-label="Permalink to &quot;국고채 투자&quot;">​</a></h3><p>채권 종류별로는 국고채의 경우, 외국인 순투자가 +19.2조원의 순유입을 기록하였으며, 이에 따라 외국인의 국고채 보유잔액도 238.7조원으로 역대 최고치를 경신하였습니다. 외국인의 국고채 보유비중 또한 22.8%로 역대 최고치를 기록하였습니다.</p><h3 id="기타-채권-투자" tabindex="-1">기타 채권 투자 <a class="header-anchor" href="#기타-채권-투자" aria-label="Permalink to &quot;기타 채권 투자&quot;">​</a></h3><p>국고채 외에도 통화안정증권(통안채)도 +5.6조원 순유입을 기록하는 등 단기물 투자자금도 순유입되었습니다. 이는 외국인 투자자들이 다양한 만기의 한국 채권에 대해 투자 관심을 보이고 있음을 시사합니다.</p><h2 id="_4️⃣-외국인-투자-확대-요인" tabindex="-1">4️⃣ 외국인 투자 확대 요인 <a class="header-anchor" href="#_4️⃣-외국인-투자-확대-요인" aria-label="Permalink to &quot;4️⃣ 외국인 투자 확대 요인&quot;">​</a></h2><p>2024년 외국인 채권투자 확대의 주요 요인은 다음과 같습니다:</p><h3 id="_1-제도적-개선" tabindex="-1">1. 제도적 개선 <a class="header-anchor" href="#_1-제도적-개선" aria-label="Permalink to &quot;1. 제도적 개선&quot;">​</a></h3><ul><li><strong>세계국채지수(WGBI) 편입 결정</strong> (2024년 10월): 글로벌 투자자들의 한국 국채에 대한 신뢰도 제고</li><li><strong>국제예탁결제기구 국채통합계좌 개통</strong> (2024년 6월): 외국인 투자 절차 간소화</li><li><strong>외환시장 구조개선</strong> (2024년 7월): 외환거래 접근성 향상</li></ul><h3 id="_2-경제적-요인" tabindex="-1">2. 경제적 요인 <a class="header-anchor" href="#_2-경제적-요인" aria-label="Permalink to &quot;2. 경제적 요인&quot;">​</a></h3><ul><li>글로벌 금리인하 추세에 따른 투자심리 개선</li><li>한국 경제의 견고한 펀더멘털에 대한 신뢰</li><li>상대적으로 매력적인 금리 수준</li></ul><h3 id="_3-시장-환경" tabindex="-1">3. 시장 환경 <a class="header-anchor" href="#_3-시장-환경" aria-label="Permalink to &quot;3. 시장 환경&quot;">​</a></h3><ul><li>국고채 시장의 유동성 개선</li><li>투자 인프라의 지속적 발전</li></ul><h2 id="_5️⃣-투자-규모-변화-추이" tabindex="-1">5️⃣ 투자 규모 변화 추이 <a class="header-anchor" href="#_5️⃣-투자-규모-변화-추이" aria-label="Permalink to &quot;5️⃣ 투자 규모 변화 추이&quot;">​</a></h2><p>외국인의 중장기 채권보유잔액과 연도별 채권보유잔액은 지속적인 증가 추세를 보이고 있습니다. 특히 2023-2024년 월별 외국인 채권 순투자 추이를 보면, 2024년 들어 순투자 규모가 크게 확대된 것을 확인할 수 있습니다.</p><h2 id="_6️⃣-향후-전망" tabindex="-1">6️⃣ 향후 전망 <a class="header-anchor" href="#_6️⃣-향후-전망" aria-label="Permalink to &quot;6️⃣ 향후 전망&quot;">​</a></h2><p>WGBI 편입 효과가 본격화되는 2026년 4월부터는 더욱 대규모의 외국인 자금 유입이 예상됩니다. 지수 추종자금 유입에 따라 약 500~600억불 규모의 외국인 투자자금이 유입될 것으로 전망되며, 지수 추종자금 외에도 액티브 자금 등의 추가 유입도 기대됩니다.</p><p>이러한 외국인 투자 확대는 다음과 같은 긍정적 효과를 가져올 것으로 예상됩니다:</p><ul><li><strong>금리 안정화</strong>: 국민, 기업, 정부의 자금 조달비용 절감</li><li><strong>외환시장 안정</strong>: 외국인 자금유입에 따른 외환시장 안정성 제고</li><li><strong>국채 수요기반 확충</strong>: 장기적인 패시브 자금 유입으로 안정적인 중장기 재정운용 기반 마련</li><li><strong>국가 신인도 향상</strong>: 글로벌 금융시장에서 우리 경제의 위상 제고</li></ul><h2 id="_7️⃣-결론" tabindex="-1">7️⃣ 결론 <a class="header-anchor" href="#_7️⃣-결론" aria-label="Permalink to &quot;7️⃣ 결론&quot;">​</a></h2><p>2024년 외국인 채권투자는 제도적 개선과 경제적 요인이 결합되어 역대 최대 규모의 순유입을 기록했습니다. 특히 세계국채지수(WGBI) 편입 결정은 향후 지속적이고 안정적인 외국인 투자 유입의 기반을 마련했다는 점에서 매우 의미가 큽니다. 이는 한국 국채시장이 글로벌 투자자들에게 신뢰받는 선진 시장으로 발전했음을 보여주는 중요한 성과입니다.</p>',27)]))}const p=e(o,[["render",i]]);export{c as __pageData,p as default};
